 void InitializeImporter(Panel buttons){cancelImport.Content=L.T("불러오기 취소");retryImport.Content=L.T("다시 검색");generatedImport.Content=L.T("생성 부품 로그 확인");cancelImport.Visibility=retryImport.Visibility=generatedImport.Visibility=Visibility.Collapsed;buttons.Children.Add(cancelImport);buttons.Children.Add(retryImport);buttons.Children.Add(generatedImport);buttons.Children.Add(importProgress);
  cancelImport.Click+=(_,_)=>CancelImport();retryImport.Click+=async(_,_)=>{if(lastSlot!=null)await ImportRaceMenuAsync(lastSlot,lastRoot);};generatedImport.Click+=async(_,_)=>{if(lastSlot!=null&&MessageBox.Show(Window.GetWindow(this),L.T("현재 프리셋에 대응하는 게임 세션의 생성 로그인지 확인해주세요. 다른 세션의 ID라면 눈·눈썹이 잘못 연결될 수 있습니다. 이 로그를 사용할까요?"),L.T("생성 부품 확인"),MessageBoxButton.YesNo)==MessageBoxResult.Yes)await ImportRaceMenuAsync(lastSlot,lastRoot,allowGenerated:true);};
  AllowDrop=true;PreviewDragOver+=(_,e)=>{if(e.Data.GetData(DataFormats.FileDrop) is string[] paths&&paths.Length==1&&Path.GetExtension(paths[0]).Equals(".jslot",StringComparison.OrdinalIgnoreCase)){e.Effects=DragDropEffects.Copy;e.Handled=true;}};
