 public void RefreshImportLanguage(){cancelImport.Content=L.T("불러오기 취소");retryImport.Content=L.T("다시 검색");generatedImport.Content=L.T("생성 부품 로그 확인");ShowResourceRoot();if(Importing)importProgress.Text=L.T(StageLabel(lastImportStage));else if(preparedImport!=null){int w=preparedImport.Notices.Count(n=>n.Severity==ImportSeverity.Warning),c=preparedImport.Notices.Count(n=>n.Severity==ImportSeverity.NeedsConfirmation);importProgress.Text=L.F("얼굴 연결 완료 · 경고 {0} · 확인 필요 {1}. 표정 편집을 계속할 수 있습니다.",w,c);ShowImport(preparedImport.Result);}}
 public void CancelImport(){++importGeneration;importCancellation?.Cancel();importCancellation=null;cancelImport.Visibility=Visibility.Collapsed;Assets.IsEnabled=true;importProgress.Text=L.T("불러오기를 취소했습니다. 이전 얼굴과 편집 내용은 유지됩니다.");}
