 public async Task<bool> ImportRaceMenuAsync(string path,string? root=null,string? selectedExport=null,bool allowGenerated=false,Func<IReadOnlyList<FaceCandidate>,string?>? choose=null,bool reconnect=false){
  if(importerClosed)return false;if(!reconnect&&Importing&&lastSlot==path&&root==lastRoot&&selectedExport==null)return false;
  importCancellation?.Cancel();var cancellation=new CancellationTokenSource();importCancellation=cancellation;long generation=++importGeneration;lastSlot=path;try{root??=resourceRoot??GameResources.Detect();}catch(Exception e)when(ImportFiles.Expected(e)){LogImport("Environment",e);importCancellation=null;cancellation.Dispose();importProgress.Text=L.T("리소스 환경을 확인하지 못했습니다. Data 폴더를 선택하거나 다시 검색해주세요.");retryImport.Visibility=Visibility.Visible;return false;}lastRoot=root;
  if(root==null){var d=new Microsoft.Win32.OpenFolderDialog{Title=L.T("게임 Data 또는 추출한 리소스 폴더 선택")};if(d.ShowDialog(Window.GetWindow(this))!=true){CancelImport();cancellation.Dispose();return false;}root=lastRoot=d.FolderName;}
  cancelImport.Visibility=Visibility.Visible;retryImport.Visibility=generatedImport.Visibility=Visibility.Collapsed;Assets.IsEnabled=false;
  var reconnectState=reconnect?Assets.CaptureState():null;FaceAssetPanel.Snapshot? reconnected=null;
  var previewMorphs=current?.Channels.Values.SelectMany(c=>c.Morphs).Where(m=>m.Enabled).Select(m=>new Morph{Backend=m.Backend,Id=m.Id,Name=m.Name,Strength=m.Strength,Enabled=m.Enabled}).ToArray()??[];
  var progress=new Progress<string>(stage=>{if(!importerClosed&&generation==importGeneration){lastImportStage=stage;importProgress.Text=L.T(StageLabel(stage));}});
  var context=new ImportContext{Cancellation=cancellation.Token,Progress=progress,AcceptDeclaredTopology=true,AllowUnprovenGeneratedIds=allowGenerated};bool entered=false;
  PreparedFace PrepareCurrent(string? selected,bool confirmed){root=ResourceRootPreference.Validate(root!);var next=AutomaticFaceImport.Prepare(path,root,context,selected,confirmed,previewMorphs);if(reconnectState!=null){next.Result.Scene.EditOnCurrentThread();reconnected=FaceAssetPanel.PrepareReconnection(next.Result.Scene,reconnectState,context);next.Result.Scene.Resources!.VerifyCurrent();next.Result.Scene.FreezeForTransfer();}return next;}
  try{await importWorker.WaitAsync(cancellation.Token);entered=true;var next=await Task.Run(()=>PrepareCurrent(selectedExport,selectedExport!=null),cancellation.Token);
   if(importerClosed||generation!=importGeneration||cancellation.IsCancellationRequested)return false;
   if(next.AutomaticNif==null&&next.Candidates.Any(c=>c.Compatible)){
    string? selected;if(choose!=null)selected=choose(next.Candidates.Where(c=>c.Compatible).ToList());else{var dialog=new NifPickerDialog(next.Candidates.Where(c=>c.Compatible).Select(c=>c.Path),true){Owner=Window.GetWindow(this)};bool? accepted=dialog.ShowDialog();if(dialog.ImportCancelled){CancelImport();return false;}selected=accepted==true?dialog.SelectedPath:null;}
    if(selected!=null){next=await Task.Run(()=>PrepareCurrent(selected,true),cancellation.Token);if(importerClosed||generation!=importGeneration||cancellation.IsCancellationRequested)return false;try{await Task.Run(()=>FaceAssociations.Remember(path,selected,next.Result.Scene.Resources!),cancellation.Token);}catch(Exception e)when(ImportFiles.Expected(e)){next.Result.Messages.Add("Association was not saved: "+e.GetType().Name);}}
   }
