   next.Result.Scene.EditOnCurrentThread();var old=Assets.CaptureState();var previous=lastImport;var previousRoot=resourceRoot;var oldPrepared=preparedImport;
   try{committingImport=true;stagedResources=next.Result.Scene.Resources;stagedMorphResources=next.MorphResources;stagedMorphNames=previewMorphs.Where(m=>m.Backend=="MFEE").Select(m=>m.Name).ToArray();preparedImport=next;resourceRoot=root;lastImport=next.Result;next.Result.Scene.ShowHair=hair.IsChecked==true;if(reconnected!=null)Assets.RestoreState(reconnected);else Assets.AdoptImportedScene(next.Result.Scene);ShowImport(next.Result);}catch{lastImport=previous;resourceRoot=previousRoot;preparedImport=oldPrepared;try{Assets.RestoreState(old);}catch(Exception restore){LogImport("Rollback",restore);}throw;}finally{committingImport=false;}
   int warnings=next.Notices.Count(n=>n.Severity==ImportSeverity.Warning),confirmations=next.Notices.Count(n=>n.Severity==ImportSeverity.NeedsConfirmation);importProgress.Text=L.F("얼굴 연결 완료 · 경고 {0} · 확인 필요 {1}. 표정 편집을 계속할 수 있습니다.",warnings,confirmations);retryImport.Visibility=warnings+confirmations>0?Visibility.Visible:Visibility.Collapsed;generatedImport.Visibility=next.Notices.Any(n=>n.Code=="generated-identity")?Visibility.Visible:Visibility.Collapsed;RememberResourceRoot(root);return true;
  }catch(OperationCanceledException){if(!importerClosed&&generation==importGeneration)importProgress.Text=L.T("불러오기를 취소했습니다. 이전 얼굴과 편집 내용은 유지됩니다.");return false;}catch(Exception e)when(ImportFiles.Expected(e)||e is System.Reflection.TargetInvocationException){if(!importerClosed&&generation==importGeneration){LogImport("Import",e);importDetails.Text=e+"\n"+importDetails.Text;importProgress.Text=L.T(e is System.Text.Json.JsonException or InvalidDataException or FormatException?"프리셋 또는 얼굴 리소스를 해석하지 못했습니다. 원본 파일과 활성 모드를 확인해주세요. 이전 작업은 유지됩니다.":"얼굴 리소스에 접근하지 못했습니다. 경로·접근 권한을 확인하거나 다시 검색해주세요. 이전 작업은 유지됩니다.");retryImport.Visibility=Visibility.Visible;}return false;
  }finally{if(entered)importWorker.Release();if(!importerClosed&&generation==importGeneration){importCancellation=null;Assets.IsEnabled=true;cancelImport.Visibility=Visibility.Collapsed;}cancellation.Dispose();}
